INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (24, 2, NULL, 'Practicas en Desarrollo de Software Multiplataforma', 'Desarrollo', 'Apoyo en el desarrollo de aplicaciones. Tareas orientadas a la integracion de interfaces frontend y manipulacion de bases de datos con SQL y pyhton para el backend.', 'Manejo de pyhton, SQL y Data Analysis. Uso de Adobe XD para diseno de interfaces.', 'Presencial', 'Quito', 160, 6, '08:00 - 14:00', 1, false, NULL, '2026-06-16 22:47:55.982702', '2026-06-16 22:47:55.982702');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (9, 9, 9, 'Desarrollador Backend Junior', 'Tecnología', 'Buscamos un estudiante apasionado por el desarrollo backend para unirse a nuestro equipo. Trabajarás en proyectos reales aplicando metodologías ágiles.', '- Estudiante de 7mo semestre en adelante.
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (26, 1, 1, 'Desarrollo de Software Móvil y Servicios Web', 'Desarrollo Móvil', 'Participación en la construcción de soluciones para dispositivos celulares y tablets. Las actividades principales involucran el consumo de APIs, la estructuración de interfaces de usuario ágiles y la persistencia de información en sistemas relacionales del lado del servidor.', 'Se requiere destreza armando pantallas interactivas multiplataforma. Nociones sólidas en la creación de endpoints y administración de tablas de datos. Interés por la experiencia de usuario (UX) y el rendimiento en la nube.', 'Híbrido', 'Guayaquil', 144, 6, 'Lunes a Viernes', 1, false, '2026-07-11', '2026-06-20 10:45:04.778491', '2026-06-22 00:04:03.535112');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (18, 2, 2, 'Data Scientist / Ingeniero Machine Learning', 'Tecnología', 'Buscamos un estudiante de la carrera de Software con interés en Ciencia de Datos, Machine Learning e Inteligencia Artificial para apoyar en el desarrollo de proyectos de análisis de datos y modelos predictivos. El candidato participará en el procesamiento, limpieza y análisis de grandes volúmenes de información utilizando Python, Pandas y Scikit-Learn, contribuyendo a la optimización de procesos mediante soluciones basadas en datos. Se valorará la capacidad analítica, el aprendizaje continuo y el interés por desarrollar modelos de machine learning aplicados a problemas reales.', 'Estudiante de la carrera de Software.
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (17, 1, 1, 'Análisis de Datos y Desarrollo Web', 'Sistemas', 'Buscamos un estudiante de Ingeniería en Software o carreras afines para apoyar en el análisis de datos y el desarrollo de soluciones web internas. El practicante participará en la limpieza y procesamiento de datos, generación de reportes, automatización de tareas mediante scripts y apoyo en el desarrollo de módulos web utilizando tecnologías frontend y backend. Tendrá la oportunidad de trabajar con datos reales y colaborar con equipos multidisciplinarios en proyectos tecnológicos.', 'Requisitos en texto
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (23, 2, NULL, 'Practicas en Data Science e IA', 'Tecnología', 'Participacion en el analisis profundo de informacion y creacion de sistemas inteligentes. Apoyo en el entrenamiento de redes neuronales y algoritmos de aprendizaje automatico para extraer valor de los datos.', 'Conocimiento en Data Science y Machine Learning. Manejo de pyhton y SQL. Interes en analisis estadistico y modelos de IA avanzados.', 'Remoto', 'Guayaquil', 160, 6, '09:00 - 15:00', 2, false, NULL, '2026-06-16 22:47:55.982702', '2026-06-16 22:47:55.982702');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (25, 2, NULL, 'Practicas en Ingenieria de Datos y Backend', 'Backend', 'Desarrollo de pipelines de datos y microservicios orientados al analisis de informacion en el ecosistema Microsoft. Apoyo en la arquitectura de software.', 'Conocimientos en .NET y bases de datos relacionales como SQL. Interes en la implementacion de algoritmos.', 'Híbrido', 'Cuenca', 160, 6, '09:00 - 15:00', 3, true, NULL, '2026-06-16 22:47:55.982702', '2026-06-16 22:47:55.982702');
INSERT INTO public.vacantes (vacante_id, institucion_id, supervisor_id, titulo, area, descripcion, requisitos, modalidad, ubicacion, total_horas, horas_diarias, horario, cupos, activo, fecha_expiracion, creado_en, actualizado_en) VALUES (10, 10, 10, 'Asistente de Desarrollo Frontend', 'Desarrollo web', 'Buscamos un estudiante con interés en el desarrollo web para apoyar al equipo en la creación y mejora de aplicaciones internas en frontend. Durante las prácticas participará en tareas de implementación de interfaces, corrección de errores y desarrollo de nuevas funcionalidades, trabajando junto a desarrolladores con experiencia.', '- Conocimientos básicos de HTML, CSS y JavaScript.
